//! The `glean_schema` library (`write_symbol_info/glean/`, unwrapped in the
//! OCaml: its modules are the top-level `Hack`, `Src`, `Fbthrift`,
//! `Gencode`, `Builtin`, `Fact_id` and `Util`). `hack`, `src`, `fbthrift` and
//! `gencode` are generated by `glean_schema_gen.py` from the OCaml modules of
//! the same names, which are themselves generated from the Glean schema.

pub mod builtin;
pub mod fact_id;
pub mod fbthrift;
pub mod gencode;
pub mod hack;
pub mod src;
pub mod util;

/// The JSON of the generated modules against facts written by the OCaml
/// (`tests/oracle_facts.json`, made by `tests/collect_oracle_facts.py` from
/// `hh_single_type_check --glean-index` on test files): for every fact,
/// reading its key with the generated `of_json_key` and writing it back with
/// `to_json_key` gives the OCaml's text, byte for byte (the order of the
/// fields included).
#[cfg(test)]
mod tests {
    use crate::yojson::safe as yojson;

    #[test]
    fn round_trip_of_oracle_facts() {
        let text = include_str!("tests/oracle_facts.json");
        let preds = match yojson::from_string(text).unwrap() {
            yojson::T::List(l) => l,
            _ => panic!("not a list"),
        };
        let mut checked = 0;
        for p in &preds {
            let name = match super::util::test_json::field(p, "predicate") {
                yojson::T::String(s) => s.clone(),
                _ => panic!(),
            };
            // "hack.ClassDeclaration.6"
            let parts: Vec<&str> = name.split('.').collect();
            let (schema, pred) = (parts[0], parts[1]);
            for fact in super::util::test_json::list(super::util::test_json::field(p, "facts")) {
                let key = super::util::test_json::field(fact, "key");
                let back = match schema {
                    "hack" => super::hack::round_trip_key(pred, key),
                    "src" => super::src::round_trip_key(pred, key),
                    "gencode" => super::gencode::round_trip_key(pred, key),
                    _ => None,
                }
                .unwrap_or_else(|| panic!("no predicate {}", name));
                assert_eq!(yojson::to_string(&back), yojson::to_string(key), "{}", name);
                if let Some(v) = super::util::test_json::field_opt(fact, "value") {
                    assert_eq!(pred, "IndexerInputsHash");
                    let v2 = super::hack::indexer_inputs_hash::to_json_value(
                        &super::hack::indexer_inputs_hash::of_json_value(v),
                    );
                    assert_eq!(yojson::to_string(&v2), yojson::to_string(v));
                }
                checked += 1;
            }
        }
        assert!(checked > 900, "{checked}");
    }
}
